(function(){"use strict";self.onmessage=async({data:m})=>{try{const r=performance.now(),s=await fetch("/engine.wasm");if(!s.ok)throw Error("Engine could not load");const{instance:u}=await WebAssembly.instantiate(await s.arrayBuffer(),{}),t=u.exports,{geo:w,valid:n,rain:a,source:i,growth:c,diffusion:f,resistance:l,startKa:g}=m;t.front_init(n.length);for(const[e,o,p]of w.edges)n[e]&&n[o]&&t.front_edge(e,o,p*(1+l/(1+(a[e]+a[o])/200)));t.front_solve(i,2*Math.sqrt(c*f));const d=new Float32Array(t.memory.buffer,t.front_ptr(),n.length),h=Array.from(d,e=>Number.isFinite(e)?g-e/1e3:null);self.postMessage({arrivalKa:h,growth:c,diffusion:f,resistance:l,startKa:g,source:i,runtime:performance.now()-r})}catch(r){self.postMessage({error:r instanceof Error?r.message:"Could not calculate this scenario"})}}})();
